// Extract tweet data
const webhookData = $input.first().json.body;
const tweetData = $('Fetch Tweet Data').first().json.data;
const systemPromptData = $('Get Active System Prompt').first().json;

// Parse tweet information
const tweetUrl = webhookData.tweet_url;
const tweetId = tweetUrl.split('/status/')[1].split('?')[0];
const engagementGoal = webhookData.engagement_goal || 'increase engagement';

// Extract tweet content
const tweetText = tweetData.text || '';
const tweetAuthor = tweetData.includes?.users?.[0]?.username || 'unknown';

// Extract image URLs if present
const imageUrls = [];
if (tweetData.includes?.media) {
  tweetData.includes.media.forEach(media => {
    if (media.type === 'photo' && media.url) {
      imageUrls.push(media.url);
    } else if (media.preview_image_url) {
      imageUrls.push(media.preview_image_url);
    }
  });
}

// Construct the full prompt for the Vision/Writing Agent
const systemPrompt = systemPromptData.prompt_text;
const userPrompt = `
## TWEET TO ANALYZE:

**Author:** @${tweetAuthor}
**Tweet Text:** "${tweetText}"
**Images:** ${imageUrls.length > 0 ? imageUrls.join(', ') : 'No images'}
**Tweet URL:** ${tweetUrl}

## ENGAGEMENT GOAL:
${engagementGoal}

## YOUR TASK:
Analyze this tweet (including any images) and generate an engaging reply that achieves the engagement goal. Follow the process outlined in your system prompt.
`.trim();

// Return structured data for next nodes
return [{
  json: {
    // Tweet data
    tweet_url: tweetUrl,
    tweet_id: tweetId,
    tweet_text: tweetText,
    tweet_author: tweetAuthor,
    tweet_image_urls: imageUrls,

    // Prompts
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    engagement_goal: engagementGoal,

    // Metadata for tracking
    prompt_version_id: systemPromptData.id,
    prompt_version_number: systemPromptData.version,

    // Timestamp
    requested_at: new Date().toISOString()
  }
}];

