// Extract the generated reply from LLM response
const llmResponse = $input.first().json;
const generatedText = llmResponse.choices[0].message.content;

// Parse the structured response
// The LLM should return: TWEET ANALYSIS, ENGAGEMENT STRATEGY, GENERATED REPLY
const replyMatch = generatedText.match(/\*\*GENERATED REPLY:\*\*\s*([\s\S]+?)(?=\n\n|$)/i);
const analysisMatch = generatedText.match(/\*\*TWEET ANALYSIS:\*\*\s*([\s\S]+?)(?=\n\n|\*\*)/i);
const strategyMatch = generatedText.match(/\*\*ENGAGEMENT STRATEGY:\*\*\s*([\s\S]+?)(?=\n\n|\*\*)/i);

const generatedReply = replyMatch ? replyMatch[1].trim() : generatedText.trim();
const tweetAnalysis = analysisMatch ? analysisMatch[1].trim() : 'Analysis not provided';
const engagementStrategy = strategyMatch ? strategyMatch[1].trim() : 'Strategy not provided';

// Get input data
const inputData = $('Construct Vision Agent Prompt').first().json;

// Return all data needed for user review
return [{
  json: {
    ...inputData,

    // LLM output
    generated_reply: generatedReply,
    tweet_analysis: tweetAnalysis,
    engagement_strategy: engagementStrategy,
    full_llm_response: generatedText,

    // Model metadata
    model_used: llmResponse.model,
    tokens_used: llmResponse.usage?.total_tokens || 0,
    generation_time_ms: Date.now() - new Date(inputData.requested_at).getTime()
  }
}];

// Get all necessary context for the Prompt Optimizer Agent
const visionData = $('Parse Vision Agent Response').first().json;
const formData = $input.first().json.data;

// Construct the optimization prompt
const optimizationPrompt = `
## CONTEXT FOR SYSTEM PROMPT OPTIMIZATION

You are analyzing a case where an AI-generated tweet reply received user feedback. Your task is to improve the system prompt based on this feedback.

---

### CURRENT SYSTEM PROMPT (Version ${visionData.prompt_version_number}):
${visionData.system_prompt}

---

### ORIGINAL TWEET ANALYSIS:
The Vision/Writing Agent analyzed the tweet as follows:
${visionData.tweet_analysis}

**Tweet Text:** "${visionData.tweet_text}"
**Tweet Author:** @${visionData.tweet_author}
**Images:** ${visionData.tweet_image_urls.length > 0 ? visionData.tweet_image_urls.join(', ') : 'None'}

---

### ENGAGEMENT GOAL:
${visionData.engagement_goal}

---

### GENERATED REPLY:
${visionData.generated_reply}

---

### USER FEEDBACK:
**Decision:** ${formData.decision}
**Rating:** ${formData['rating (1-5)']} out of 5
**Critique:** ${formData['your feedback / critique'] || 'No specific feedback provided'}

---

## YOUR TASK:

Analyze why the generated reply didn't fully meet the user's expectations (rating: ${formData['rating (1-5)']}/5) and propose specific improvements to the system prompt.

Follow the analysis process outlined in your system prompt to generate:
1. Issue identification
2. Root cause analysis
3. Proposed changes
4. Updated system prompt
5. Rationale
6. Testing criteria
`.trim();

return [{
  json: {
    // Original data
    ...visionData,

    // User feedback
    user_decision: formData.decision,
    user_feedback: formData['your feedback / critique'] || '',
    user_rating: parseInt(formData['rating (1-5)']),
    reviewed_at: new Date().toISOString(),

    // Optimization context
    optimization_prompt: optimizationPrompt
  }
}];

