// Extract the updated system prompt from optimizer response
const optimizerResponse = $input.first().json;
const optimizerOutput = optimizerResponse.choices[0].message.content;

// Parse the UPDATED SYSTEM PROMPT section
const updatedPromptMatch = optimizerOutput.match(/\*\*UPDATED SYSTEM PROMPT:\*\*\s*([\s\S]+?)(?=\n\n\*\*RATIONALE:|$)/i);
const rationaleMatch = optimizerOutput.match(/\*\*RATIONALE:\*\*\s*([\s\S]+?)(?=\n\n\*\*|$)/i);
const proposedChangesMatch = optimizerOutput.match(/\*\*PROPOSED CHANGES:\*\*\s*([\s\S]+?)(?=\n\n\*\*|$)/i);

const updatedPromptText = updatedPromptMatch ? updatedPromptMatch[1].trim() : null;
const rationale = rationaleMatch ? rationaleMatch[1].trim() : 'Not provided';
const proposedChanges = proposedChangesMatch ? proposedChangesMatch[1].trim() : 'Not provided';

if (!updatedPromptText) {
  throw new Error('Failed to parse updated system prompt from optimizer response');
}

// Get context data
const contextData = $('Prepare Optimization Context').first().json;

return [{
  json: {
    ...contextData,

    // New prompt data
    new_prompt_text: updatedPromptText,
    optimization_rationale: rationale,
    proposed_changes: proposedChanges,
    full_optimizer_response: optimizerOutput,

    // Metadata
    new_version_number: contextData.prompt_version_number + 1,
    optimizer_model: optimizerResponse.model,
    optimized_at: new Date().toISOString()
  }
}];

// Prepare final data for logging
const inputData = $input.first().json;

// Check if we're coming from approved path or optimization path
const fromOptimization = inputData.new_prompt_text !== undefined;

if (fromOptimization) {
  // Get the new prompt ID from the save operation
  const saveResult = $('Save New Prompt Version').first().json;

  return [{
    json: {
      ...inputData,
      new_prompt_created: true,
      new_prompt_id: saveResult.id
    }
  }];
} else {
  // Approved path - no optimization
  return [{
    json: {
      ...inputData,
      new_prompt_created: false,
      new_prompt_id: null
    }
  }];
}
